// A single captured pointer controls movement; other fingers may drag the view.
export function bindJoystick(area,knob,onMove,win=window,doc=document){
 let active=null;
 function move(x,y){const rect=area.getBoundingClientRect(),radius=Math.max(1,Math.min(rect.width,rect.height)*.35),dx=x-(rect.left+rect.width/2),dy=y-(rect.top+rect.height/2),distance=Math.hypot(dx,dy),ratio=distance>radius?radius/distance:1,nx=dx*ratio/radius,ny=dy*ratio/radius;knob.style.transform=`translate(${nx*radius}px, ${ny*radius}px)`;if(Math.hypot(nx,ny)<.12)onMove(0,0);else onMove(nx,ny)}
 function stop(){if(active===null)return;active=null;knob.style.transform='translate(0px, 0px)';area.classList.remove('active');onMove(0,0)}
 if('PointerEvent' in win){area.addEventListener('pointerdown',e=>{if(active!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();active=e.pointerId;area.classList.add('active');try{area.setPointerCapture(e.pointerId)}catch{}move(e.clientX,e.clientY)});win.addEventListener('pointermove',e=>{if(e.pointerId!==active)return;if(e.cancelable)e.preventDefault();move(e.clientX,e.clientY)},true);for(const type of ['pointerup','pointercancel'])win.addEventListener(type,e=>{if(e.pointerId===active)stop()},true);area.addEventListener('lostpointercapture',e=>{if(e.pointerId===active)stop()})}
 else{area.addEventListener('touchstart',e=>{if(active!==null)return;const t=e.changedTouches[0];if(!t)return;e.preventDefault();active=t.identifier;area.classList.add('active');move(t.clientX,t.clientY)},{passive:false});area.addEventListener('touchmove',e=>{const t=[...e.changedTouches].find(t=>t.identifier===active);if(!t)return;e.preventDefault();move(t.clientX,t.clientY)},{passive:false});for(const type of ['touchend','touchcancel'])win.addEventListener(type,e=>{if([...e.changedTouches].some(t=>t.identifier===active))stop()},true)}
 area.addEventListener('contextmenu',e=>e.preventDefault());win.addEventListener('blur',stop);win.addEventListener('pagehide',stop);doc.addEventListener('visibilitychange',()=>{if(doc.hidden)stop()});return stop;
}
